from collections import defaultdict
class Solution:
    def differenceOfDistinctValues(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        diag = defaultdict(list)
        for r in range(m):
            for c in range(n):
                diag[r - c].append((r, c))
        la = [[0]*n for _ in range(m)]
        rb = [[0]*n for _ in range(m)]
        for cells in diag.values():
            s = set()
            for r, c in cells:
                la[r][c] = len(s)
                s.add(grid[r][c])
            s = set()
            for r, c in reversed(cells):
                rb[r][c] = len(s)
                s.add(grid[r][c])
        return [[abs(la[r][c] - rb[r][c]) for c in range(n)] for r in range(m)]

