class Solution {
public:
    vector<vector<int>> differenceOfDistinctValues(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        map<int, vector<pair<int,int>>> diag;
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                diag[r - c].push_back({r, c});
        vector<vector<int>> la(m, vector<int>(n)), rb(m, vector<int>(n)), ans(m, vector<int>(n));
        for (auto& [k, cells] : diag) {
            unordered_set<int> s;
            for (auto& [r, c] : cells) { la[r][c] = s.size(); s.insert(grid[r][c]); }
            s.clear();
            for (int i = cells.size() - 1; i >= 0; i--) {
                auto [r, c] = cells[i];
                rb[r][c] = s.size(); s.insert(grid[r][c]);
            }
        }
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                ans[r][c] = abs(la[r][c] - rb[r][c]);
        return ans;
    }
};

