class Solution {
    public int[][] differenceOfDistinctValues(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        Map<Integer, List<int[]>> diag = new TreeMap<>();
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                diag.computeIfAbsent(r - c, x -> new ArrayList<>()).add(new int[]{r, c});
        int[][] la = new int[m][n], rb = new int[m][n];
        for (List<int[]> cells : diag.values()) {
            Set<Integer> s = new HashSet<>();
            for (int[] p : cells) { la[p[0]][p[1]] = s.size(); s.add(grid[p[0]][p[1]]); }
            s.clear();
            for (int i = cells.size() - 1; i >= 0; i--) {
                int[] p = cells.get(i);
                rb[p[0]][p[1]] = s.size(); s.add(grid[p[0]][p[1]]);
            }
        }
        int[][] ans = new int[m][n];
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                ans[r][c] = Math.abs(la[r][c] - rb[r][c]);
        return ans;
    }
}

