var differenceOfDistinctValues = function(grid) {
    const m = grid.length, n = grid[0].length;
    const diag = new Map();
    for (let r = 0; r < m; r++)
        for (let c = 0; c < n; c++) {
            const k = r - c;
            if (!diag.has(k)) diag.set(k, []);
            diag.get(k).push([r, c]);
        }
    const la = Array.from({length: m}, () => new Array(n).fill(0));
    const rb = Array.from({length: m}, () => new Array(n).fill(0));
    for (const cells of diag.values()) {
        let s = new Set();
        for (const [r, c] of cells) { la[r][c] = s.size; s.add(grid[r][c]); }
        s = new Set();
        for (let i = cells.length - 1; i >= 0; i--) {
            const [r, c] = cells[i];
            rb[r][c] = s.size; s.add(grid[r][c]);
        }
    }
    return la.map((row, r) => row.map((_, c) => Math.abs(la[r][c] - rb[r][c])));
};

