class Solution:
    def differenceOfDistinctValues(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        ans = [[0]*n for _ in range(m)]
        for r in range(m):
            for c in range(n):
                a, b = set(), set()
                i, j = r - 1, c - 1
                while i >= 0 and j >= 0:
                    a.add(grid[i][j]); i -= 1; j -= 1
                i, j = r + 1, c + 1
                while i < m and j < n:
                    b.add(grid[i][j]); i += 1; j += 1
                ans[r][c] = abs(len(a) - len(b))
        return ans

